"use client";

import { cn } from "@/lib/utils";
import { Separator as SeparatorPrimitive } from "radix-ui";
import type * as React from "react";

/**
 * Separator (separator-radix)
 *
 * A one-pixel horizontal or vertical rule that separates content, decorative by default and semantic on request.
 *
 * Exports: Separator
 *
 * Props:
 * - Separator: React.ComponentProps<typeof SeparatorPrimitive.Root>
 *   - orientation: "horizontal" | "vertical" (default "horizontal"). Layout axis.
 *   - decorative: boolean (default true). When true the separator is presentational and hidden from assistive technology.
 *
 * Theme tokens (shadcn names, from your theme): --border.
 *
 * Accessibility:
 * - Decorative by default, so assistive technology skips it.
 * - Set decorative={false} when the rule separates content semantically; it then exposes role="separator" with aria-orientation.
 *
 * Customize:
 * - The line color comes from --border and its thickness is 1px.
 * - Pass className for spacing, such as my-4, or for a different color utility.
 */

function Separator({
  className,
  orientation = "horizontal",
  decorative = true,
  ...props
}: React.ComponentProps<typeof SeparatorPrimitive.Root>) {
  return (
    <SeparatorPrimitive.Root
      className={cn(
        "shrink-0 bg-border data-[orientation=horizontal]:h-px data-[orientation=vertical]:h-full data-[orientation=horizontal]:w-full data-[orientation=vertical]:w-px",
        className
      )}
      data-slot="separator"
      decorative={decorative}
      orientation={orientation}
      {...props}
    />
  );
}

export { Separator };
